-- Issue #738 battles (ARC on #910): each finished battle is stored once by the world tick (conditional insert on battle_key = war id, attacking unit, staging arrival), so a decided battle never changes. Behind HARIMU_ARMY_BATTLES_ENABLED. Additive only.
CREATE TABLE IF NOT EXISTS army_battles (battle_key TEXT COLLATE "C" PRIMARY KEY, war_id TEXT COLLATE "C" NOT NULL, attacker_unit TEXT COLLATE "C" NOT NULL, defender_unit TEXT COLLATE "C" NOT NULL, started_at BIGINT NOT NULL, rounds INTEGER NOT NULL CHECK(rounds >= 0), status TEXT NOT NULL CHECK(status IN ('attacker_won','defender_won')), retreated TEXT CHECK(retreated IN ('attacker','defender')), attacker_strength INTEGER NOT NULL CHECK(attacker_strength >= 0), defender_strength INTEGER NOT NULL CHECK(defender_strength >= 0), recorded_at BIGINT NOT NULL);
